// Firma HMAC-SHA256 compatible con src/adapters/http/auth.js
const crypto = require('crypto');
const secret = $vars.INFLU_APPROVER_HMAC_SECRET;           // definir en n8n > Variables (nunca en el workflow)
const base = $vars.INFLU_BASE_URL;        // p. ej. https://influ-poc-orchestrator.<subdominio>.workers.dev
const item = $input.first().json;
const path = `/v1/batches/${item.body.batch_id}/decision`;
const body = { command_text: item.body.command_text, version: item.body.version, content_hash: item.body.content_hash, decided_by: item.body.decided_by };
const raw = body === null ? '' : JSON.stringify(body);
const ts = String(Math.floor(Date.now() / 1000));
const nonce = crypto.randomBytes(18).toString('base64url');
const bodyHash = crypto.createHash('sha256').update(raw).digest('hex');
const s = ['v1', ts, nonce, 'POST', path, bodyHash].join('\n');
const sig = 'v1=' + crypto.createHmac('sha256', secret).update(s).digest('hex');
return [{ json: { url: base + path, raw, headers: { 'x-influ-key-id': 'approver', 'x-influ-timestamp': ts, 'x-influ-nonce': nonce, 'x-influ-signature': sig } } }];
